read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'IMBoyMessage' -> merge_msg_IMBoyMessage(Prev, New, TrUserData);
        'E2EEMeta' -> merge_msg_E2EEMeta(Prev, New, TrUserData);
        'E2EEDeviceKey' -> merge_msg_E2EEDeviceKey(Prev, New, TrUserData);
        'PayloadText' -> merge_msg_PayloadText(Prev, New, TrUserData);
        'ReplyRef' -> merge_msg_ReplyRef(Prev, New, TrUserData);
        'PayloadImage' -> merge_msg_PayloadImage(Prev, New, TrUserData);
        'PayloadVideo' -> merge_msg_PayloadVideo(Prev, New, TrUserData);
        'PayloadAudio' -> merge_msg_PayloadAudio(Prev, New, TrUserData);
        'PayloadFile' -> merge_msg_PayloadFile(Prev, New, TrUserData);
        'PayloadLocation' -> merge_msg_PayloadLocation(Prev, New, TrUserData);
        'PayloadRevoke' -> merge_msg_PayloadRevoke(Prev, New, TrUserData);
        'PayloadEdit' -> merge_msg_PayloadEdit(Prev, New, TrUserData);
        'PayloadRead' -> merge_msg_PayloadRead(Prev, New, TrUserData);
        'PayloadRefreshToken' -> merge_msg_PayloadRefreshToken(Prev, New, TrUserData);
        'PayloadAppUpgrade' -> merge_msg_PayloadAppUpgrade(Prev, New, TrUserData);
        'PayloadDeviceKicked' -> merge_msg_PayloadDeviceKicked(Prev, New, TrUserData);
        'PayloadMsgDeleted' -> merge_msg_PayloadMsgDeleted(Prev, New, TrUserData);
        'PayloadSync' -> merge_msg_PayloadSync(Prev, New, TrUserData);
        'SyncCursor' -> merge_msg_SyncCursor(Prev, New, TrUserData);
        'PayloadSyncResult' -> merge_msg_PayloadSyncResult(Prev, New, TrUserData);
        'PayloadClientAck' -> merge_msg_PayloadClientAck(Prev, New, TrUserData);
        'PayloadClientAckConfirm' -> merge_msg_PayloadClientAckConfirm(Prev, New, TrUserData);
        'PayloadWebRTCOffer' -> merge_msg_PayloadWebRTCOffer(Prev, New, TrUserData);
        'PayloadWebRTCAnswer' -> merge_msg_PayloadWebRTCAnswer(Prev, New, TrUserData);
        'PayloadWebRTCCandidate' -> merge_msg_PayloadWebRTCCandidate(Prev, New, TrUserData);
        'PayloadWebRTCBye' -> merge_msg_PayloadWebRTCBye(Prev, New, TrUserData);
        'IMBoyBatch' -> merge_msg_IMBoyBatch(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_IMBoyMessage/3}).
merge_msg_IMBoyMessage(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{type := NFtype}} -> S2#{type => NFtype};
             {#{type := PFtype}, _} -> S2#{type => PFtype};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{from := NFfrom}} -> S3#{from => NFfrom};
             {#{from := PFfrom}, _} -> S3#{from => PFfrom};
             _ -> S3
         end,
    S5 = case {PMsg, NMsg} of
             {_, #{to := NFto}} -> S4#{to => NFto};
             {#{to := PFto}, _} -> S4#{to => PFto};
             _ -> S4
         end,
    S6 = case {PMsg, NMsg} of
             {_, #{msg_type := NFmsg_type}} -> S5#{msg_type => NFmsg_type};
             {#{msg_type := PFmsg_type}, _} -> S5#{msg_type => PFmsg_type};
             _ -> S5
         end,
    S7 = case {PMsg, NMsg} of
             {_, #{action := NFaction}} -> S6#{action => NFaction};
             {#{action := PFaction}, _} -> S6#{action => PFaction};
             _ -> S6
         end,
    S8 = case {PMsg, NMsg} of
             {#{e2ee := PFe2ee}, #{e2ee := NFe2ee}} -> S7#{e2ee => merge_msg_E2EEMeta(PFe2ee, NFe2ee, TrUserData)};
